# Candidate (B2) for TASK-SHIP-028 (dimensions_nesting_object)
def build_request(data):
    return {
        'path': '/v2/logistics/dimensions_nesting_object/task-ship-028',
        'body': {
            'parcel_dimensions_box': {
                'parcel_id': data['parcel_id'],
                'weight_grams': float(data['weight_grams']) / 1000.0,
                'length_cm': int(data['length_cm']),
                'carrier_iso': data['carrier_code'],
                'route_address': data['street_address']
            }
        },
        'headers': {
            'X-Shipment-Idempotency': 'missing-ship-idem-b2'
        }
    }

def dispatch_package(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
